for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Greedy local search for MaxCut
partition = np.random.randint(0, 2, n)

def cut_value(partition):
    cut = 0
    for u, v in edges:
        if partition[u] != partition[v]:
            cut += 1
    return cut

def gain_from_flip(vertex, partition):
    current_side = partition[vertex]
    gain = 0
    for neighbor in adj[vertex]:
        if partition[neighbor] == current_side:
            gain += 1  # New cut edge
        else:
            gain -= 1  # Lost cut edge
    return gain

# Local search
improved = True
while improved:
    improved = False
    for v in range(n):
        gain = gain_from_flip(v, partition)
        if gain > 0:
            partition[v] = 1 - partition[v]
            improved = True
